window.tcShip=async f=>{if(!f)return;const p=PL(S.products.find(x=>x.id==f.dataset.p));const d=Object.fromEntries(new FormData(f)),v=d.variant||'standard',q=Math.max(1,Math.min(5,+d.qty||1)),pick=d.delivery=='pickup';
 const ag=f.querySelector('.addr');if(ag){ag.hidden=pick;ag.querySelectorAll('[data-req]').forEach(x=>x.required=!pick)}
 if(p.direct){const q2=Math.max(1,Math.min(5,+d.qty||1)),b2=f.querySelector('.shipsum'),t=(p.price||0)*q2;b2.innerHTML=`<div class="pr"><span>${T('Item','商品','Artículo')} × ${q2}</span><b>$${t.toFixed(2)}</b></div><div class="pr"><span>${T('US shipping','美国运费','Envío en EE. UU.')}</span><b>${T('Included','已含','Incluido')}</b></div><div class="pr tot"><span>${T('Total due now','现在应付','Total a pagar ahora')}</span><b>$${t.toFixed(2)}</b></div>`;f.dataset.ship='0';return}
 const unit=(p.priceV&&p.priceV[v])||p.price||0,full=d.pay=='full',dep=DEP(p,v)*q,item=unit*q,box=f.querySelector('.shipsum');let ship=null,msg='';f.dataset.ship='';
 if(pick){ship=0}else if(/^\d{5}$/.test(d.zip||'')){box.innerHTML=T('Calculating shipping…','正在计算运费…','Calculando envío…');try{const r=await fetch(SHQ()+'?product='+encodeURIComponent(p.id)+'&variant='+encodeURIComponent(v)+'&qty='+q+'&zip='+d.zip),j=await r.json();if(j.ok){ship=+j.shipping}else msg=j.error=='zip'?T('Please enter a valid US ZIP (50 states + DC).','请填写有效的美国邮编（50 州及华盛顿特区）。','Ingresa un ZIP válido de EE. UU. (50 estados + DC).'):T('Could not get a shipping quote right now — please try again.','暂时无法计算运费，请稍后再试。','No pudimos cotizar el envío en este momento — inténtalo de nuevo.')}catch(_){msg=T('Could not get a shipping quote right now — please try again.','暂时无法计算运费，请稍后再试。','No pudimos cotizar el envío en este momento — inténtalo de nuevo.')}}
 const cur=Object.fromEntries(new FormData(f));if(cur.zip!=d.zip||cur.delivery!=d.delivery||cur.qty!=d.qty||cur.variant!=d.variant||cur.pay!=d.pay)return;
 if(ship!=null)f.dataset.ship=ship;const $$=n=>'$'+(+n).toFixed(2),sl=ship==null?(msg||T('enter your ZIP','请填写邮编','ingresa tu ZIP')):(pick?T('$0.00 (local pickup in LA)','$0.00（洛杉矶自提）','$0.00 (recogida local en LA)'):$$(ship));
 const ln=(a,b,c)=>`<div class="pr${c?' '+c:''}"><span>${a}</span><b>${b}</b></div>`;
 box.innerHTML=ln(T('Item','商品','Artículo')+(q>1?' × '+q:''),$$(item))+ln(T('US shipping','美国运费','Envío en EE. UU.'),sl,ship==null?'muted':'')+(full?ln(T('Total due now','现在应付','Total a pagar ahora'),ship==null?'—':$$(item+ship),'tot'):ln(T('Order total incl. shipping','含运费总价','Total del pedido con envío'),ship==null?'—':$$(item+ship))+ln(T('Balance later (incl. shipping)','尾款（含运费，到仓后支付）','Saldo después (con envío)'),ship==null?'—':$$(item-dep+ship))+ln(T('Deposit due now','现在付定金','Depósito a pagar ahora'),$$(dep),'tot'))};

